import pandas as pd
import numpy as np

# Load data
df = pd.read_csv('chunks_csv/outlierr/2023_gas.csv')
adj = pd.read_csv(ADJACENCY_PATH)

# Build symmetric neighbor map
neighbors = {b: set() for b in df['borough']}
for _, row in adj.iterrows():
    b = row['borough']
    n = row['neighbor']
    if b in neighbors and n in neighbors and b != n:
        neighbors[b].add(n)
        neighbors[n].add(b)

gas = df.set_index('borough')['Gas_value']
boroughs = list(df['borough'])

def compute_neighbor_avg(active_set):
    avg = {}
    for b in boroughs:
        ns = [nbr for nbr in neighbors[b] if nbr in active_set]
        if ns:
            avg[b] = gas.loc[ns].mean()
        else:
            avg[b] = np.nan
    return avg

active = set(boroughs)
threshold = 2.5

for _ in range(len(boroughs)):
    avg_dict = compute_neighbor_avg(active)
    x = []
    y = []
    for b in active:
        if not np.isnan(avg_dict.get(b, np.nan)):
            x.append(avg_dict[b])
            y.append(gas.loc[b])
    if len(x) < 3:
        break
    x = np.array(x)
    y = np.array(y)
    # OLS fit y = a + b*x
    A = np.vstack([x, np.ones(len(x))]).T
    b_slope, a_int = np.linalg.lstsq(A, y, rcond=None)[0]
    # Residuals for active boroughs
    resids = {}
    for b in active:
        if not np.isnan(avg_dict.get(b, np.nan)):
            pred = a_int + b_slope * avg_dict[b]
            resids[b] = gas.loc[b] - pred
    if not resids:
        break
    r_vals = np.array(list(resids.values()))
    med = np.median(r_vals)
    mad = np.median(np.abs(r_vals - med)) * 1.4826
    if mad == 0 or np.isnan(mad):
        mad = np.std(r_vals)
    z_scores = {b: (resids[b] - med) / mad for b in resids}
    worst = max(resids.keys(), key=lambda bb: abs(z_scores[bb]))
    if abs(z_scores[worst]) < threshold:
        break
    active.remove(worst)

# Final robust regression on cleaned active set
avg_dict = compute_neighbor_avg(active)
x = []
y = []
for b in active:
    if not np.isnan(avg_dict.get(b, np.nan)):
        x.append(avg_dict[b])
        y.append(gas.loc[b])
x = np.array(x)
y = np.array(y)
A = np.vstack([x, np.ones(len(x))]).T
b_slope, a_int = np.linalg.lstsq(A, y, rcond=None)[0]

# Final robust scale (MAD) from active set
resids = {}
for b in active:
    if not np.isnan(avg_dict.get(b, np.nan)):
        pred = a_int + b_slope * avg_dict[b]
        resids[b] = gas.loc[b] - pred
r_vals = np.array(list(resids.values()))
med = np.median(r_vals)
mad = np.median(np.abs(r_vals - med)) * 1.4826
if mad == 0 or np.isnan(mad):
    mad = np.std(r_vals)

target = "City of London"
if target in avg_dict and not np.isnan(avg_dict.get(target, np.nan)):
    avg_target = avg_dict[target]
else:
    ns = [nbr for nbr in neighbors[target] if nbr in active]
    if not ns:
        ns = [nbr for nbr in neighbors[target]]
    avg_target = gas.loc[ns].mean() if ns else np.nan

pred_target = a_int + b_slope * avg_target
res_target = gas.loc[target] - pred_target
z_target = (res_target - med) / mad

if z_target > threshold:
    label = "OUTLIER - HIGH"
elif z_target < -threshold:
    label = "OUTLIER - LOW"
else:
    label = "NOT AN OUTLIER"

print(f"FINAL ANSWER: {label} (z = {z_target})")
